var e=[{title:`Possibili sostituti`,text:`Uno zaino chiuso con il contenuto distribuito in modo uniforme può aggiungere resistenza a uno squat o a un carry. Le bottiglie d’acqua funzionano come pesi leggeri da mano, e un gradino robusto può sostituire una piattaforma bassa per esercizi. Questi oggetti non hanno dimensioni standard né indicazioni di peso, quindi carico ed equilibrio possono cambiare senza preavviso.`},{title:`I mobili sono un rischio importante`,text:`Una sedia da pranzo può scivolare o ribaltarsi durante dip, step-up o push-up inclinati, e molti tavoli non reggono un rematore a corpo libero tirato da sotto il bordo. Non dare mai per scontato che un normale tavolo, un asciugamano, una maniglia di porta o una mensola possano reggere il tuo peso corporeo. Se un’impostazione dipende da una forza o da un ancoraggio di cui non sei sicuro, scegli un altro esercizio.`},{title:`Controlla ogni oggetto`,text:`Assicurati che la superficie non scivoli, che il contenitore non perda né abbia maniglie rotte e che le cinghie dello zaino non si stiano strappando. Distribuisci il peso in modo che non oscilli all’improvviso. Evita contenitori di vetro, bordi metallici affilati e pile instabili di libri. Allenati su un pavimento libero, lontano da qualsiasi cosa fragile.`},{title:`Progredisci lentamente`,text:`Inizia con un movimento semplice e un piccolo carico. Ripetizioni lente e ripetibili sono meglio di equilibrismi complicati. Se non riesci a pesare l’oggetto in modo affidabile, annota l’impostazione e un’idea approssimativa della resistenza invece di un numero preciso. Mantieni ogni aumento abbastanza piccolo da restare in controllo.`},{title:`Usare TrainUp`,text:`Un oggetto di uso domestico non è una panca, un rack, una sbarra per trazioni o una stazione al cavo. In Profilo, inserisci un tipo di panca o una sbarra per trazioni solo per l’attrezzatura vera. Quando non puoi essere sicuro che un mobile sia sicuro, scegli esercizi a corpo libero che non richiedono appoggio.`}];var a=[{label:`Mayo Clinic: sicurezza e tecnica dell’allenamento coi pesi`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Libreria di esercizi ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:e,sources:a};export{n as default,e as sections,a as sources};